"""Fixed bilingual semantics for the five supplied reference diagrams."""
import json
from pathlib import Path
S=Path(__file__).resolve().parents[1]/'docs/sources/m05-04/replacement-2026-11-08'
def build():
 data={}
 def add(name,kind,zh,en,desc,edesc,rows):
  data[name]={lang:{'kind':kind,'caption':cap,'description':description,'items':[{'title':r[0 if lang=='zh' else 2],'body':r[1 if lang=='zh' else 3]} for r in rows]} for lang,cap,description in [('zh',zh,desc),('en',en,edesc)]}
 add('roles','cards','圖 1｜CVE、CWE、CPE 與現場證據','Figure 1 | CVE, CWE, CPE and local evidence','三種平行觀察角度共同支援設備適用性判斷。','Three parallel perspectives jointly support a device applicability judgment.',[
 ('CVE','發生哪個漏洞？','CVE','Which vulnerability?'),('CWE','缺陷屬於哪一類？','CWE','Which weakness type?'),('CPE','可能影響什麼產品？','CPE','Which products may be affected?'),('對照版本、設定、修補與現場證據','由三個觀察角度核對實際條件','Compare versions, settings, patches and local evidence','Check actual conditions using all three perspectives'),('這台實際設備到底有沒有受到影響？','這才是資安工程師真正需要回答的問題','Is this actual device affected?','This is the question the security engineer needs to answer')])
 add('identifier','cards','圖 2｜CVE-2021-44228 編號結構','Figure 2 | CVE-2021-44228 identifier structure','這是真實的 Log4Shell 編號；年份不是漏洞被發現或首次遭利用的必然日期。','This is the real Log4Shell identifier; its year does not necessarily indicate discovery or first exploitation.',[('CVE','漏洞識別系統','CVE','Vulnerability identifier system'),('2021','編號年份','2021','Identifier year'),('44228','識別流水號','44228','Sequence number')])
 add('lookup','flow','圖 3｜公開資料到現場查證','Figure 3 | From public records to local verification','建議查證順序；資料完整度與更新先後需逐案核對。','Suggested investigation order; verify completeness and freshness for each case.',[('CVE 官方紀錄','這個漏洞是什麼？編號是否有效？有哪些參考資料？','Official CVE record','What is it? Is the ID valid? Which references are available?'),('NVD 補充分析','可能受影響的產品條件、CWE 類型、CVSS 嚴重度等（視資料完整程度）','NVD enrichment','Affected product conditions, CWE types and CVSS severity, depending on completeness'),('廠商安全公告','哪些版本真的受影響？有什麼限制？應更新到哪個版本？','Vendor advisory','Which versions are affected? What conditions apply? Which update is needed?'),('自己的系統與資產紀錄','實際安裝版本、設定、修補狀態及執行中的元件','Local system and asset records','Installed versions, configuration, patch status and running components')])
 add('finding','cards','圖 4｜掃描器發現：待確認','Figure 4 | Scanner finding: pending verification','以下是虛構教學案例，不是真實掃描結果或 CVE。','Fictional teaching case, not a real scan result or CVE.',[('產品','Orange Document Server','Product','Orange Document Server'),('偵測版本','2.4','Detected version','2.4'),('公告範圍','2.4～2.6','Advisory range','2.4–2.6'),('漏洞條件','必須開啟文件預覽功能','Vulnerability condition','Document preview must be enabled'),('修補版本','2.7','Fixed version','2.7')])
 add('evidence','cards','圖 5｜四種證據層次','Figure 5 | Four evidence levels','教學層次不表示每項弱點都須利用測試，成功利用也不能證明過去遭入侵。','These teaching levels do not require exploitation for every finding, nor establish prior compromise from a successful test.',[('發現疑似弱點（Potential Finding）','掃描器比對到某個 CVE，表示值得調查，尚未確認適用條件。','Potential Finding','A scanner match merits investigation; applicability remains unconfirmed.'),('確認受到影響（Confirmed Vulnerability）','有足夠證據確認產品、版本、設定與修補狀態符合漏洞成立條件。','Confirmed Vulnerability','Sufficient product, version, configuration and patch evidence establishes applicability.'),('驗證實際可利用性（Validated Exploitability）','在授權範圍內，以受控測試證明漏洞確實可以產生特定安全影響。','Validated Exploitability','An authorized, controlled test demonstrates a specific security impact.'),('發現實際入侵（Evidence of Compromise）','透過日誌、鑑識等證據，確認曾發生未經授權的利用或入侵活動。','Evidence of Compromise','Logs or forensic evidence establish unauthorized exploitation or intrusion.')])
 return data
if __name__=='__main__':(S/'diagrams.json').write_text(json.dumps(build(),ensure_ascii=False,indent=2)+'\n');print('Five paired figure models written')
